INSERT INTO collection_pages VALUES('59e2dd670075040b1320942be3e4ef1296cf2d0ebc3985cf7737858bc3324bcf','6cfbc2346fdb2d7ce205a5ea3ae17cba8f0275d74df57fc795cb32049956b2f0','{"hasNext":false,"items":[{"author":{"account":{"login":"rk4rohankumar","providerType":"User"},"email":"rwpmns@gmail.com","name":"Rohan Kumar"},"authoredDate":"2026-10-02T04:34:58Z","committedDate":"2026-10-02T04:34:58Z","committer":{"account":{"login":"web-flow","providerType":"User"},"email":"noreply@github.com","name":"GitHub"},"observedAt":"2026-10-08T18:42:32.690Z","repositoryId":927283710,"sha":"3be8d44bf6f54e592af9ce222d830e9476099576"},{"author":{"account":{"login":"rk4rohankumar","providerType":"User"},"email":"rwpmns@gmail.com","name":"Rohan Kumar"},"authoredDate":"2026-04-19T14:32:20Z","committedDate":"2026-04-19T14:32:20Z","committer":{"account":{"login":"rk4rohankumar","providerType":"User"},"email":"rwpmns@gmail.com","name":"Rohan Kumar"},"observedAt":"2026-10-08T18:42:32.690Z","repositoryId":927283710,"sha":"2d76f4feebc5adeff98bf41dfc8c872fb6cbbb02"}],"observedAt":"2026-10-08T18:42:32.690Z","raw":[{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/96616262?v=4","events_url":"https://api.github.com/users/rk4rohankumar/events{/privacy}","followers_url":"https://api.github.com/users/rk4rohankumar/followers","following_url":"https://api.github.com/users/rk4rohankumar/following{/other_user}","gists_url":"https://api.github.com/users/rk4rohankumar/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/rk4rohankumar","id":96616262,"login":"rk4rohankumar","node_id":"U_kgDOBcI_Rg","organizations_url":"https://api.github.com/users/rk4rohankumar/orgs","received_events_url":"https://api.github.com/users/rk4rohankumar/received_events","repos_url":"https://api.github.com/users/rk4rohankumar/repos","site_admin":false,"starred_url":"https://api.github.com/users/rk4rohankumar/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/rk4rohankumar/subscriptions","type":"User","url":"https://api.github.com/users/rk4rohankumar","user_view_type":"public"},"comments_url":"https://api.github.com/repos/rk4rohankumar/cuisines-child-app/commits/3be8d44bf6f54e592af9ce222d830e9476099576/comments","commit":{"author":{"date":"2026-10-02T04:34:58Z","email":"rwpmns@gmail.com","name":"Rohan Kumar"},"comment_count":0,"committer":{"date":"2026-10-02T04:34:58Z","email":"noreply@github.com","name":"GitHub"},"message":"feat: shell-ready remote — singleton shared, async bootstrap, lazy media, a11y (#1)\n\nThe host shell loads this remote at runtime and initialises it with its own\nshare scope, so the remote must negotiate React/react-dom/framer-motion/axios\nas singletons instead of bundling eager copies, and its entry has to be async\nso the shared modules are resolved before the first render. publicPath is\n''auto'' in production (dev keeps ''/'') so the build works from any origin.\n\nAlso clears the CRA scaffolding (logo/test/vitals/App.css, CRA comments in\nindex.html, PNG icons replaced by an inline SVG favicon), swaps the external\nvia.placeholder.com fallback for an inline SVG, uses TheMealDB''s `/preview`\nthumbnail on cards with an aspect-ratio wrapper to avoid layout shift, and\ngives the recipe modal a real focus trap (Escape closes, Tab cycles inside,\nfocus returns to the opener). Card markup no longer nests a link inside a\nbutton, and red text/buttons use red-600/700 for AA contrast.\n\nCo-authored-by: Claude Fable 5.1 <noreply@anthropic.com>","tree":{"sha":"d61459ec02b2c55ef091925a24d5ae879497e1e5","url":"https://api.github.com/repos/rk4rohankumar/cuisines-child-app/git/trees/d61459ec02b2c55ef091925a24d5ae879497e1e5"},"url":"https://api.github.com/repos/rk4rohankumar/cuisines-child-app/git/commits/3be8d44bf6f54e592af9ce222d830e9476099576","verification":{"payload":"tree d61459ec02b2c55ef091925a24d5ae879497e1e5\nparent 2d76f4feebc5adeff98bf41dfc8c872fb6cbbb02\nauthor Rohan Kumar <rwpmns@gmail.com> 1790915698 +0530\ncommitter GitHub <noreply@github.com> 1790915698 +0530\n\nfeat: shell-ready remote — singleton shared, async bootstrap, lazy media, a11y (#1)\n\nThe host shell loads this remote at runtime and initialises it with its own\nshare scope, so the remote must negotiate React/react-dom/framer-motion/axios\nas singletons instead of bundling eager copies, and its entry has to be async\nso the shared modules are resolved before the first render. publicPath is\n''auto'' in production (dev keeps ''/'') so the build works from any origin.\n\nAlso clears the CRA scaffolding (logo/test/vitals/App.css, CRA comments in\nindex.html, PNG icons replaced by an inline SVG favicon), swaps the external\nvia.placeholder.com fallback for an inline SVG, uses TheMealDB''s `/preview`\nthumbnail on cards with an aspect-ratio wrapper to avoid layout shift, and\ngives the recipe modal a real focus trap (Escape closes, Tab cycles inside,\nfocus returns to the opener). Card markup no longer nests a link inside a\nbutton, and red text/buttons use red-600/700 for AA contrast.\n\nCo-authored-by: Claude Fable 5.1 <noreply@anthropic.com>","reason":"valid","signature":"-----BEGIN PGP SIGNATURE-----\n\nwsFcBAABCAAQBQJqvzRyCRC1aQ7uu5UhlAAA7TUQADmtrRTbIys+oIa71nFZoSUf\nGCkfYHSkGhIxMf/2uvW2K+sauTI0QsurK9PnpHnmonQuyz/kLgKUyL6xpK9wttw7\njrdMVnfX5IOrmqEr9/5z3Y5A0HfP/+BA9dUkIe6LAU5BZ9SlYPk6qLjlQF1RdWbz\nRUXfpufZrcHau3BkXEX1lL+YYtxf6w64YA5WA0D1Ii9Nqt8tBypbDgmkSFrvTZL5\nYovRstvlB3sqvaaHZrLg7cvGS5zaTBfxPGS04nNgFgIKqiSHooJbRepCE7x0Hi8j\nhwZE3N5XBl/MGH51Vlw79vJS37HEC8R4pZXPbwq7XTxQfG8km7eLUQlztcZ+tM9T\nesHR5lrwPdJDV391sdqFhesbT0kLVPp1dbDHES5hzIZMCBfvisqbY7fVkyBpcxkN\nBcNf21qF0hwYyn392ukMJtB3nj6Pb9taEhcU7/iiK71IkMWNhHeZwCU16ZIdAITZ\n+dafUGoPan8XQi2Z4NzKOzZ3b8FM6F9sP9rtpraQUxj/WrFpls5/KJexToH5Apyc\nScApVhCDoukOC8RB6nozM4tjRANDvpuNNqQufXi19nbjTIlL1n6zEWBo21EBvzoF\njomuZMMWhHotBDXANPvkT6G4V1jaWLCFPqT6uTXnZAm5xf9hM0DU5X3wD7571Q9E\neg4RwIhm0l3tRtOEGKxO\n=G3oS\n-----END PGP SIGNATURE-----\n","verified":true,"verified_at":"2026-10-02T04: